import sys; sys.path.insert(0, "Tools/prd_ledger/88")
from _lib import c, table, save

c(14, "§3.1 table (verbatim); §3.1", "data-caveat", "Prioritised unions (verbatim): " + table("## 3.1 The prioritised picture", 0) + " — five findings: money (227 paid or charged, 107 hit a problem after paying), paying before seeing (132), trust (197), charges people did not agree to (93, concentrated from June 2021), a thin product (U:value_content 105, 21.43%); negative_any 429 (87.55%); praise_any 90 (18.37%).", "n/a", "mixed", "negative_any 429 / 87.55%; value_content 105; praise_any 90", "none", "table", "generalisable", ["6756282701"], "", "")

c(15, "§3.2 table (verbatim); §3.2", "monetization", "The paywall (verbatim): " + table("## 3.2 The paywall", 0) + " — a purchase screen stood between install and use (PAY_HARD_WALL 96, 1.15★: 'It asks for your name, then tries to sell you a subscription'; 'you can't get past the subscription page without making a selection. There is no free version'); the 'free' label made it worse (33, 1.06★: 'listing it as Free in the store seems bad faith to me'); no trial or a trial that costs money (58; PAID_TRIAL 29: 'Was met with a $0.49 charge to even enter the app'); the weekly plan drew particular anger (20: 'charge EIGHT DOLLARS A WEEK'; '69 kroners per WEEK!!'); paying did not unlock everything (38, 30 of them buyers: 'Not worth 3 different life time membership fees I had to pay'); pressure (UPSELL_NAGS 36: 'I've seen 4 attempted at making me buy upgrades in the first 1 minute'; COUNTDOWN 46); price itself (54, 1.52★) usually against how little the app contained; would-be buyers name conditions (PAY_CONDITIONAL_WILLING 8: a real trial — 'If I had a 14 or even 7 day trial I would have actually given it ago'; sync — 'Want my money? Add cross device syncing.'; honest advertising).", "hard wall; paid trial; weekly plan; stacked content; nags", "blocked-conversion", "HARD_WALL 96; FREE_LABEL 33 / 1.06★; NO_FREE_TRIAL 58; PAID_TRIAL 29; WEEKLY 20; PREMIUM_INCOMPLETE 38; UPSELL_NAGS 36; COUNTDOWN 46; PRICE_TOO_HIGH 54; CONDITIONAL_WILLING 8", "product-rule", "High-priority", "generalisable", ["6802711687", "7169002761", "6812397351", "6824404281", "7092708463", "6771958876", "7227200950", "7188581081", "6819531238", "6743042296", "6818850233", "6827257273", "6852598066"], "", "")

c(16, "§3.3 table (verbatim); §3.3", "must-never-break", "Billing (verbatim): " + table("## 3.3 Billing", 0) + " — double charges came from the offer (26); charged more than the price shown (PRICE_MISMATCH 10: 'Said it was charging me 39.99. I was charged 75 freaking dollars'); the wrong plan (15: 'purchased a year subscription… still charged the weekly rate after my trial'); trials that billed early (TRIAL_CONVERSION 35, 25 in Jun–Dec 2021; TRIAL_SHORTER 8: 'they offer you a 3 day subscription but charge you $31 immediately'; 'the trial that said ONE MONTH… automatically charged 20€'); cancelling did not stop charges (CHARGED_AFTER_CANCEL 21; CANT_CANCEL 34; UNAUTHORISED 17: 'I sent three emails asking to cancel that night'; 'subscribed on their website and now can't cancel'; 'they've been charging me for months'); web checkout and another merchant's name (19 + 4; 8 of 19 web buyers could not get the purchase into the app); refunds requested 64, refused 7 ('tried to request a refund TWICE from Apple and was denied'; 'I was told I had to pruebe I used the app at least during 7 days'), received 4; BANK_ACTION 8.", "n/a", "1★-burst", "DOUBLE 26; PRICE_MISMATCH 10; WRONG_PLAN 15; TRIAL_CONVERSION 35; TRIAL_SHORTER 8; AFTER_CANCEL 21; CANT_CANCEL 34; UNAUTHORISED 17; WEB 19; OTHER_MERCHANT 4; REFUND_REQUEST 64 / REFUSED 7 / RECEIVED 4; BANK 8", "must-never-break", "High-priority", "generalisable", ["7090478565", "6867290877", "7637881316", "7855046339", "7058565193", "7793704069", "8776444875", "6998518011", "7862429664", "6838351982"], "", "")

c(17, "§3.4 table (verbatim); §3.4", "monetization", "Paid users (verbatim): " + table("## 3.4 Paid users", 0) + " — PAID_EXPLICIT 182 (37.14%, 1.18★); CHARGED_NOT_CHOSEN 45 (1.07★); PAID_REGRET 65 (13.27%); PAID_NO_ACCESS 28 (5.71%: 'Despite that I cannot access app: Error. There was a problem with App Store'); PAID_SATISFIED 1 (0.20%).", "n/a", "churn", "PAID 182 / 1.18★; REGRET 65; NO_ACCESS 28; SATISFIED 1", "must-never-break", "High-priority", "generalisable", ["7197019939", "7391062590"], "", "")

c(18, "§3.5 table (verbatim); §3.5", "dont", "Acquisition, ads and the review gate (verbatim): " + table("## 3.5 Acquisition", 0) + " — misleading ads (72, 1.14★: personality types, cleaning checklists, templates and challenges shown in Facebook, Instagram, TikTok and tumblr ads the app did not contain); ads inside the app (21, all before 2021-04-07: 'Impossible to use because of enormous number of long video ads'); rate to unlock (REVIEW_GATE 13: 'it forced me to leave a review to unlock the first habit tracker'; 'writing a review in exchange for trying the app'); distrust of the rating (11: 'I'm assuming those are paid reviews'; 'I was a fool for trusting the 4.4 star rating'; a claim the developer deleted a previous review).", "social ads; in-app video ads; rate-to-unlock", "1★-burst", "ADS_MISLEADING 72 / 1.14★; ADS_IN_APP 21; REVIEW_GATE 13; REVIEWS_DISTRUST 11; SOCIAL_AD 53", "dont", "High-priority", "generalisable", ["6781000648", "6830128790", "7261488968", "7029621975", "7257033437", "7441400045"], "", "")

c(19, "§3.6 table (verbatim); §3.6", "insight", "Content and value (verbatim): " + table("## 3.6 Content and value", 0) + " — U:value_content 105 (21.43%, 1.33★): little inside (CONTENT_THIN 54: 'There are like 5 challenges and they are laughable'); low quality (19: 'the cleaning list is like Day 1 do the dishes, day 2 make the bed'); not for me (13: 'aimed females and/or those in a relationship'); basic habit functions missing (FUNC_LIMITED 13: 'you can't change the name of a habit, you can't add more habit categories, you cant change the order'; counting habits like '8 glasses of water' cannot be tracked); free substitutes (COMP_FREE_ALTERNATIVE 33: the phone's reminders and notes, a journal, Pinterest, Google lists); COMP_NAMED_APP 7 (Streaks, Fabulous, Moodlinks, HabitMinder, Habit RPG, Any.do, Outlook).", "thin preset challenges; no rename, categories, reorder, counts", "complaint", "value_content 105 / 21.43% / 1.33★; THIN 54; LOW_QUALITY 19; NOT_PERSONAL 13; FUNC_LIMITED 13; FREE_ALTERNATIVE 33; NAMED_APP 7", "none", "High-priority", "generalisable", ["6818382575", "7079611283", "6775201953", "6839825405", "7569539286"], "", "")

c(20, "§3.7 table (verbatim); §3.7", "must-never-break", "Defects and friction (verbatim): " + table("## 3.7 Defects and friction", 0) + " — U:defect_any 83 (16.94%), functional 47 (9.59%): UI and stability (DEF_BUG_UI 28: layout broken on iPhone SE, stuck set-up, black or blank screens, 'The app constantly crashes'); reminders (DEF_REMINDERS 18 — 'for a habit app, the core loop': 'the habit notifications are sent at the complete wrong time'; 'it goes back to the default time'); tracking (DEF_CANT_TRACK 7: 'unable to mark my habits done'); spelling (QUALITY_SPELLING 12, all before 2021-03-06: 'Makr a list of short term goals'); confusing UX 19; English only (LANG_NOT_AVAILABLE 6); no account or sync (9: 'cannot login without having to pay full payment again').", "n/a", "complaint", "defect_any 83 / 16.94%; BUG_UI 28; REMINDERS 18; CANT_TRACK 7; SPELLING 12; UX_CONFUSING 19; LANG 6; NO_ACCOUNT_SYNC 9", "must-never-break", "High-priority", "generalisable", ["6830845373", "7159739863", "7105962949", "7010825409", "6809718942", "7287583575", "7521527537", "6776685014", "7559782122"], "", "")

c(21, "§3.8 table (verbatim); §3.8", "must-have", "Support (verbatim): " + table("## 3.8 Support", 0) + " — SUPPORT_UNRESPONSIVE 59 (12.04%, 1.22★): emails unanswered, 'Failed to send email', no contact details; UNHELPFUL 12 ('they told me we don't do refunds'; told they 'may have accidentally selected the weekly subscription'); HELPFUL 2, both Spanish and both refunds ('they issued a full refund in under 24 hours'); SUPPORT_QUESTION 13 used the review to ask how to cancel or get access.", "n/a", "complaint", "UNRESPONSIVE 59; UNHELPFUL 12; HELPFUL 2; QUESTION 13", "must-have", "High-priority", "generalisable", ["6778267872", "7084713878", "8034491173", "7879858284"], "", "")

c(22, "§3.9 table (verbatim); §3.9", "timeline", "Trust and churn (verbatim): " + table("## 3.9 Trust and churn", 0) + " — SCAM_LANGUAGE 105 (21.43%, 1.04★), 104 of 105 one-star, in seven languages (Abzocke, Betrug, truffa, estafa, timo, robo, arnaque, мошенники); WARN_OTHERS 91 (18.57%); CHURN_STATED 37 (7.55%); ESCALATION_EXTERNAL 11 ('They've been reported to Apple'); U:lost_user_signal 128 (26.12%).", "n/a", "1★-burst", "SCAM 105 / 1.04★; WARN_OTHERS 91; CHURN 37; ESCALATION 11; lost_user 128 / 26.12%", "none", "High-priority", "generalisable", ["6842631902"], "", "")

c(23, "§3.10 tables (verbatim); §3.10", "audience", "Praise, outcomes and use (verbatim): " + table("## 3.10 Praise", 0) + " || " + table("## 3.10 Praise", 1) + " — U:praise_any 90 (3.81★); OUT_BENEFIT 20 (4.50★: 'This app has been a life-changer for me'; 'I've tried to form a running habit for many years… now I got HabitBox and my life completely changed'); PRAISE_GENERIC 40 mostly under 60 characters; PRAISE_DESIGN 8 ('I tried 10 other apps and honestly this one is my favorite! I love the dark theme'); PRAISE_CONCEPT 15 at 1.53★; uses: USE_CLEANING 12; USE_MENTAL_NEURO 5 — ADHD ('I have ADHD and need help organizing my life'), OCD, brain injury, addiction recovery.", "n/a", "mixed", "praise_any 90; OUT_BENEFIT 20 / 4.50★; GENERIC 40; DESIGN 8; CONCEPT 15 / 1.53★; USE_CLEANING 12; USE_MENTAL_NEURO 5", "none", "High-priority", "generalisable", ["6776858603", "7224000412", "6823277588", "7088376254", "7153915411", "6974200378", "6800574896", "6866515956"], "", "")

c(24, "§3.11 table (verbatim); §3.11; §3.12 table (verbatim)", "feature", "Requests (verbatim): " + table("## 3.11 Requests", 0) + " — U:request_any 17 (3.47%): more challenges 7, customisation 5, sync or an account 2, Spanish 2, an iPad layout 1 — 'requests are few because most reviewers never reached the product'. Privacy (verbatim): " + table("## 3.12 Privacy", 0), "n/a", "complaint", "request_any 17 / 3.47%; MORE_CHALLENGES 7; PRIV_PAYMENT_DETAILS 8", "none", "table", "generalisable", ["6852598066", "7142966385"], "", "few requests because few reached the product")

